/**
 * Regenerates the committed ingest fixtures in fixtures/ingest/{video,subtitles}/ that model
 * real-world files: 1080p-class pictures with cropped heights, 10-bit HEVC, 5.1 AC-3/AAC sound,
 * dual-language audio, several text subtitle tracks and a chapter, plus French sidecar subtitles.
 *
 * Every picture and sound is generated by ffmpeg (lavfi `testsrc2` + noise, `sine` tones) and every
 * title and subtitle line is invented, so the fixtures carry no third-party content
 * (rule REL-LIC-05). The track layouts are what the tests assert, and fixture_expectations.json
 * describes them.
 *
 * Usage: bun packages/ingest-core/scripts/generate-ingest-fixtures.ts
 * Output is not byte-stable across ffmpeg/x264/x265 versions; regenerate and commit the files together.
 */
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const PKG_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const VIDEO_DIR = join(PKG_ROOT, "fixtures/ingest/video");
const SUBTITLE_DIR = join(PKG_ROOT, "fixtures/ingest/subtitles");
const WORK_DIR = mkdtempSync(join(tmpdir(), "sf-ingest-fixtures-"));

const FPS = "24000/1001";

type Audio = { codec: "aac" | "ac3"; layout: "stereo" | "5.1" | "5.1(side)"; bitrate: string; language?: string; title?: string; tone: number };
type Subtitle = { language: string; title: string };
type Fixture = {
  file: string;
  seconds: number;
  video: { codec: "h264" | "hevc"; width: number; height: number; bitrate: string; language?: string; colour: string };
  audio: Audio[];
  subtitles: Subtitle[];
  chapter?: string;
};

const SALTMARSH_SUBTITLES: Subtitle[] = [
  { language: "eng", title: "English" },
  { language: "eng", title: "English" },
  { language: "eng", title: "English" },
  { language: "fre", title: "French" },
  { language: "fre", title: "French Forced" },
];

const saltmarshEpisode = (file: string, seconds: number, colour: string): Fixture => ({
  file,
  seconds,
  video: { codec: "hevc", width: 1920, height: 1080, bitrate: "4500k", language: "eng", colour },
  audio: [{ codec: "ac3", layout: "5.1(side)", bitrate: "448k", language: "eng", title: "English AC3", tone: 440 }],
  subtitles: SALTMARSH_SUBTITLES,
  chapter: "Chapter 1",
});

const FIXTURES: Fixture[] = [
  {
    file: "Orchard (2017).mkv",
    seconds: 10.2,
    video: { codec: "h264", width: 1920, height: 800, bitrate: "1100k", colour: "0x2e7d32" },
    audio: [{ codec: "aac", layout: "stereo", bitrate: "160k", tone: 330 }],
    subtitles: [],
  },
  {
    file: "Cartographer (2001).mkv",
    seconds: 10.1,
    video: { codec: "h264", width: 1920, height: 796, bitrate: "4700k", colour: "0x6a1b9a" },
    audio: [{ codec: "aac", layout: "5.1", bitrate: "384k", tone: 550 }],
    subtitles: [],
  },
  {
    file: "Le Phare de l'Étang (2001) [FR-EN].mkv",
    seconds: 10.2,
    video: { codec: "hevc", width: 1920, height: 800, bitrate: "300k", colour: "0x01579b" },
    audio: [
      { codec: "aac", layout: "5.1", bitrate: "128k", language: "fre", title: "VF Français", tone: 392 },
      { codec: "aac", layout: "5.1", bitrate: "128k", language: "eng", title: "VO Anglais", tone: 494 },
    ],
    subtitles: [
      { language: "fre", title: "Français (Forced)" },
      { language: "fre", title: "Français" },
      { language: "eng", title: "Anglais" },
    ],
    chapter: "01 - Prologue",
  },
  saltmarshEpisode("Saltmarsh - S01E01 - Low Tide.mkv", 10.2, "0x37474f"),
  saltmarshEpisode("Saltmarsh - S01E02 - Spring Tide.mkv", 10.25, "0x4e342e"),
  saltmarshEpisode("Saltmarsh - S02E01 - Neap Tide.mkv", 10.2, "0x1a237e"),
  saltmarshEpisode("Lodgers - S01E01 - The New Lodger.mkv", 10.2, "0xbf360c"),
];

/** French lines for the Orchard sidecar: enough text for language detection, saved as Latin-1 like many older subtitle files. */
const ORCHARD_FRENCH_LINES = [
  "Le verger appartenait à ma grand-mère.",
  "Chaque automne, nous cueillions les pommes ensemble.",
  "Elle disait que les arbres se souvenaient de tout.",
  "Je ne l'ai jamais crue, jusqu'à cet hiver-là.",
  "Il neigeait depuis trois jours sur la vallée.",
  "Personne n'osait plus sortir après la tombée de la nuit.",
  "Tu entends ce bruit, derrière la grange ?",
  "Ce n'est que le vent dans les branches.",
  "Non, écoute bien. Quelqu'un chante.",
  "Ma mère a fermé les volets sans répondre.",
  "Le lendemain, une lanterne brillait au fond du verger.",
  "Je suis allée voir, malgré l'interdiction.",
  "Les traces dans la neige menaient au vieux puits.",
  "Une voix douce m'a demandé mon prénom.",
  "J'ai menti, comme ma grand-mère me l'avait appris.",
  "Pourquoi as-tu peur ? Je garde ce verger depuis cent ans.",
  "Alors vous connaissiez ma grand-mère ?",
  "Je connais tous ceux qui ont planté un arbre ici.",
  "Elle m'a laissé une promesse à tenir.",
  "Quelle promesse ? Elle ne m'a jamais rien dit.",
  "Que chaque printemps, quelqu'un reviendrait chanter.",
  "Je ne sais pas chanter. Je n'ai jamais su.",
  "Tout le monde sait chanter quand il le faut.",
  "Au village, on préparait déjà la fête des récoltes.",
  "Mon père réparait la charrette devant la maison.",
  "Où étais-tu passée toute la matinée ?",
  "Je me promenais près de la rivière.",
  "Ne t'approche pas du puits, tu m'entends ?",
  "Pourquoi tout le monde a-t-il peur de ce verger ?",
  "Parce qu'il garde ce que nous avons oublié.",
  "Le soir de la fête, je suis retournée au verger.",
  "La lanterne m'attendait, plus brillante que jamais.",
  "J'ai fermé les yeux et j'ai commencé à chanter.",
  "Les branches se sont mises à fleurir sous la neige.",
  "Tout le village est sorti pour regarder.",
  "Ma mère pleurait en souriant.",
  "Ta grand-mère serait fière de toi.",
  "Depuis, chaque printemps, je reviens chanter au verger.",
  "Et les arbres se souviennent de nous.",
  "Fin.",
];

const srtTime = (ms: number) => {
  const pad = (n: number, w = 2) => String(n).padStart(w, "0");
  return `${pad(Math.floor(ms / 3_600_000))}:${pad(Math.floor(ms / 60_000) % 60)}:${pad(Math.floor(ms / 1000) % 60)},${pad(ms % 1000, 3)}`;
};

const srt = (lines: string[], firstMs: number, stepMs: number) =>
  lines.map((line, i) => `${i + 1}\n${srtTime(firstMs + i * stepMs)} --> ${srtTime(firstMs + i * stepMs + stepMs - 500)}\n${line}\n`).join("\n");

const ffmpeg = (args: string[]) => {
  const result = spawnSync("ffmpeg", ["-hide_banner", "-loglevel", "error", "-y", ...args], { encoding: "utf8" });
  if (result.status !== 0) throw new Error(`ffmpeg ${args.join(" ")} failed: ${result.stderr}`);
};

const generate = (fixture: Fixture) => {
  const { video, seconds } = fixture;
  const args: string[] = ["-fflags", "+bitexact"];
  args.push(
    "-f", "lavfi", "-i",
    `testsrc2=size=${video.width}x${video.height}:rate=${FPS}:duration=${seconds},` +
      `drawbox=x=0:y=0:w=iw:h=ih/6:color=${video.colour}:t=fill,noise=alls=12:allf=t`
  );
  for (const audio of fixture.audio) {
    args.push("-f", "lavfi", "-i", `sine=frequency=${audio.tone}:sample_rate=48000:duration=${seconds}`);
  }
  // Subtitle tracks start after the clip ends, like a film's first line coming after its opening, so each track is present but empty.
  const subtitleFile = join(WORK_DIR, "late.srt");
  writeFileSync(subtitleFile, srt(["…"], 60_000, 2_000));
  for (const _ of fixture.subtitles) args.push("-i", subtitleFile);
  const chapterFile = join(WORK_DIR, "chapters.txt");
  if (fixture.chapter) {
    writeFileSync(chapterFile, `;FFMETADATA1\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=0\nEND=10000\ntitle=${fixture.chapter}\n`);
    args.push("-i", chapterFile);
  }

  // Input 0 is the picture, then one input per audio track, then one per subtitle track, then the chapter file.
  args.push("-map", "0:v");
  fixture.audio.forEach((_, i) => args.push("-map", `${1 + i}:a`));
  fixture.subtitles.forEach((_, i) => args.push("-map", `${1 + fixture.audio.length + i}:s`));
  // `-map_metadata -1` would also drop the chapter title, so a fixture with a chapter takes its (otherwise empty) metadata from the chapter file.
  const chapterInput = String(1 + fixture.audio.length + fixture.subtitles.length);
  args.push("-map_metadata", fixture.chapter ? chapterInput : "-1");
  if (fixture.chapter) args.push("-map_chapters", chapterInput);

  if (video.codec === "h264") {
    args.push("-c:v", "libx264", "-profile:v", "high", "-pix_fmt", "yuv420p", "-preset", "medium");
  } else {
    args.push("-c:v", "libx265", "-profile:v", "main10", "-pix_fmt", "yuv420p10le", "-preset", "fast", "-x265-params", "log-level=error");
  }
  args.push("-b:v", video.bitrate, "-maxrate", video.bitrate, "-bufsize", video.bitrate, "-g", "48", "-flags:v", "+bitexact");
  if (video.language) args.push("-metadata:s:v:0", `language=${video.language}`);

  fixture.audio.forEach((audio, i) => {
    // One sine fills every channel of the layout.
    args.push(`-filter:a:${i}`, `aformat=channel_layouts=mono,pan=${audio.layout}|${channelSpread(audio.layout)}`);
    args.push(`-c:a:${i}`, audio.codec, `-b:a:${i}`, audio.bitrate, "-ar", "48000");
    if (audio.language) args.push(`-metadata:s:a:${i}`, `language=${audio.language}`);
    if (audio.title) args.push(`-metadata:s:a:${i}`, `title=${audio.title}`);
  });
  args.push("-flags:a", "+bitexact");

  fixture.subtitles.forEach((subtitle, i) => {
    args.push(`-c:s:${i}`, "srt", `-metadata:s:s:${i}`, `language=${subtitle.language}`, `-metadata:s:s:${i}`, `title=${subtitle.title}`);
  });
  // No stream is flagged default or forced: the tests read language and title only.
  args.push("-disposition:v", "0", "-disposition:a", "0");
  if (fixture.subtitles.length > 0) args.push("-disposition:s", "0");
  args.push("-t", String(seconds), join(VIDEO_DIR, fixture.file));
  ffmpeg(args);
};

const channelSpread = (layout: Audio["layout"]) => {
  const channels = layout === "stereo" ? ["FL", "FR"] : layout === "5.1" ? ["FL", "FR", "FC", "LFE", "BL", "BR"] : ["FL", "FR", "FC", "LFE", "SL", "SR"];
  return channels.map((c) => `${c}=c0`).join("|");
};

mkdirSync(VIDEO_DIR, { recursive: true });
mkdirSync(SUBTITLE_DIR, { recursive: true });
try {
  for (const fixture of FIXTURES) {
    generate(fixture);
    console.info(`[ingest-fixtures] wrote video/${fixture.file} (${statSync(join(VIDEO_DIR, fixture.file)).size} bytes)`);
  }
  writeFileSync(join(SUBTITLE_DIR, "Orchard (2017).fr.srt"), Buffer.from(srt(ORCHARD_FRENCH_LINES, 69_000, 3_500), "latin1"));
  writeFileSync(
    join(SUBTITLE_DIR, "Saltmarsh - S01E01 - Low Tide.fr.srt"),
    srt(["Bonjour, c'est un sous-titre de test", "Deuxieme ligne de sous-titre", "Troisieme ligne francaise"], 1_000, 3_000)
  );
  console.info("[ingest-fixtures] wrote subtitles/Orchard (2017).fr.srt, subtitles/Saltmarsh - S01E01 - Low Tide.fr.srt");
} finally {
  rmSync(WORK_DIR, { recursive: true, force: true });
}
